private volatile Config config;              // Java 5+: sound publication

Config config() {
    Config c = config;                       // one volatile read (fast path)
    if (c == null) {
        synchronized (this) {
            c = config;
            if (c == null) config = c = Config.load();
        }
    }
    return c;
}

